update public.products set description='A substantial bone-in goat leg suited to roasting, grilling, slow cooking, soups, stews and portioning into smaller goat-meat cuts.', handling_protocols=array['Keep refrigerated or frozen and separate from ready-to-eat foods.','Use clean knives and boards when portioning and clean surfaces thoroughly afterwards.','For an intact goat leg, cook to at least 63°C / 145°F with a 3-minute rest.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within about 3–5 days.','For longer storage, freeze at about -18°C or below and use within about 6–9 months for best quality.']::text[] where name='Goat Leg (Waka)' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
